 121→func newDisableCmd() *cobra.Command {
 122→	var useProjectSettings bool
 123→	var uninstall bool
 124→	var force bool
 125→
 126→	cmd := &cobra.Command{
 127→		Use:   "disable",
 128→		Short: "Disable Entire in current project",
 129→		Long: `Disable Entire integrations in the current project.
 130→
 131→By default, this command will disable Entire. Hooks will exit silently and commands will
 132→show a disabled message.
 133→
 134→To completely remove Entire integrations from this repository, use --uninstall:
 135→  - .entire/ directory (settings, logs, metadata)
 136→  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)
 137→  - Session state files (.git/entire-sessions/)
 138→  - Shadow branches (entire/<hash>)
 139→  - Agent hooks`,
 140→		RunE: func(cmd *cobra.Command, _ []string) error {
 141→			ctx := cmd.Context()
 142→			if uninstall {
 143→				return runUninstall(ctx, cmd.OutOrStdout(), cmd.ErrOrStderr(), force)
 144→			}
 145→			return runDisable(ctx, cmd.OutOrStdout(), useProjectSettings)
 146→		},
 147→	}
 148→
 149→	cmd.Flags().BoolVar(&useProjectSettings, "project", false, "Update .entire/settings.json instead of .entire/settings.local.json")
 150→	cmd.Flags().BoolVar(&uninstall, "uninstall", false, "Completely remove Entire from this repository")
 151→	cmd.Flags().BoolVar(&force, "force", false, "Skip confirmation prompt (use with --uninstall)")
 152→
 153→	return cmd
