 156→// runEnableInteractive runs the interactive enable flow.
 157→// agents must be provided by the caller (via detectOrSelectAgent).
 158→func runEnableInteractive(ctx context.Context, w io.Writer, agents []agent.Agent, localDev, useLocalSettings, useProjectSettings, forceHooks, skipPushSessions, telemetry bool) error {
 159→	// Uninstall hooks for agents that were previously active but are no longer selected
 160→	if err := uninstallDeselectedAgentHooks(ctx, w, agents); err != nil {
 161→		return fmt.Errorf("failed to clean up deselected agents: %w", err)
 162→	}
 163→
 164→	// Setup agent hooks for all selected agents
 165→	for _, ag := range agents {
 166→		if _, err := setupAgentHooks(ctx, ag, localDev, forceHooks); err != nil {
 167→			return fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err)
 168→		}
 169→	}
 170→
 171→	// Check if this is a first-time setup before creating directories/loading settings.
 172→	// settings.IsSetUp checks if .entire/settings.json exists on disk.
 173→	isFirstSetup := !settings.IsSetUp(ctx)
 174→
 175→	// Setup .entire directory
 176→	if _, err := setupEntireDirectory(ctx); err != nil {
 177→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 178→	}
 179→
 180→	// Load existing settings to preserve other options (like strategy_options.push)
 181→	settings, err := LoadEntireSettings(ctx)
 182→	if err != nil {
 183→		// If we can't load, start with defaults
 184→		settings = &EntireSettings{}
 185→	}
 186→	// Update the specific fields
 187→	settings.LocalDev = localDev
 188→	settings.Enabled = true
 189→	// Set commit_linking and clean up deprecated strategy field.
 190→	// New installations get "always" (auto-link); existing repos get "prompt" written
 191→	// explicitly so the settings file reflects the current spec.
 192→	if settings.CommitLinking == "" {
 193→		if isFirstSetup {
 194→			settings.CommitLinking = CommitLinkingAlways
 195→		} else {
 196→			settings.CommitLinking = CommitLinkingPrompt
 197→		}
 198→	}
 199→	settings.Strategy = "" //nolint:staticcheck // Intentionally clearing deprecated field during setup
 200→
 201→	// Set push_sessions option if --skip-push-sessions flag was provided
 202→	if skipPushSessions {
 203→		if settings.StrategyOptions == nil {
 204→			settings.StrategyOptions = make(map[string]interface{})
 205→		}
 206→		settings.StrategyOptions["push_sessions"] = false
 207→	}
 208→
 209→	// Determine which settings file to write to
 210→	// First run always creates settings.json (no prompt)
 211→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
 212→	if err != nil {
 213→		entireDirAbs = paths.EntireDir // Fallback to relative
 214→	}
 215→	shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, useLocalSettings, useProjectSettings)
 216→
 217→	if showNotification {
 218→		fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
 219→		fmt.Fprintln(w, "  Use --project to update the project settings file.")
 220→	}
 221→
 222→	// Save settings to the appropriate file.
 223→	// commit_linking and strategy cleanup always go to settings.json (the project file)
 224→	// so there's a single source of truth that users edit.
 225→	if shouldUseLocal {
 226→		// Save user-specific overrides to local (without commit_linking — that belongs in project settings)
 227→		localSettings := *settings
 228→		localSettings.CommitLinking = ""
 229→		localSettings.Strategy = "" //nolint:staticcheck // Clear deprecated field from local too
 230→		if err := SaveEntireSettingsLocal(ctx, &localSettings); err != nil {
 231→			return fmt.Errorf("failed to save local settings: %w", err)
 232→		}
 233→		// Migrate project settings.json: clear deprecated strategy, write commit_linking
 234→		if err := migrateProjectSettings(ctx); err != nil {
 235→			return fmt.Errorf("failed to migrate project settings: %w", err)
 236→		}
 237→	} else {
 238→		if err := SaveEntireSettings(ctx, settings); err != nil {
 239→			return fmt.Errorf("failed to save settings: %w", err)
 240→		}
 241→	}
 242→
 243→	if _, err := strategy.InstallGitHook(ctx, true, localDev); err != nil {
 244→		return fmt.Errorf("failed to install git hooks: %w", err)
 245→	}
 246→	strategy.CheckAndWarnHookManagers(ctx, w, localDev)
 247→	fmt.Fprintln(w, "✓ Hooks installed")
 248→
 249→	configDisplay := configDisplayProject
 250→	if shouldUseLocal {
 251→		configDisplay = configDisplayLocal
 252→	}
 253→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplay)
 254→
 255→	// Ask about telemetry consent (only if not already asked)
 256→	fmt.Fprintln(w)
 257→	if err := promptTelemetryConsent(settings, telemetry); err != nil {
 258→		return fmt.Errorf("telemetry consent: %w", err)
 259→	}
 260→	// Save again to persist telemetry choice
 261→	if shouldUseLocal {
 262→		localSettings := *settings
 263→		localSettings.CommitLinking = ""
 264→		localSettings.Strategy = "" //nolint:staticcheck // Keep deprecated field out of local
 265→		if err := SaveEntireSettingsLocal(ctx, &localSettings); err != nil {
 266→			return fmt.Errorf("failed to save local settings: %w", err)
 267→		}
 268→	} else {
 269→		if err := SaveEntireSettings(ctx, settings); err != nil {
 270→			return fmt.Errorf("failed to save settings: %w", err)
 271→		}
 272→	}
 273→
 274→	if err := strategy.EnsureSetup(ctx); err != nil {
 275→		return fmt.Errorf("failed to setup strategy: %w", err)
 276→	}
 277→
 278→	fmt.Fprintln(w, "\nReady.")
 279→
 280→	return nil
 281→}
