 283→// runEnable is a simple enable that just sets the enabled flag (for programmatic use).
 284→func runEnable(ctx context.Context, w io.Writer) error {
 285→	settings, err := LoadEntireSettings(ctx)
 286→	if err != nil {
 287→		return fmt.Errorf("failed to load settings: %w", err)
 288→	}
 289→
 290→	settings.Enabled = true
 291→	if err := SaveEntireSettings(ctx, settings); err != nil {
 292→		return fmt.Errorf("failed to save settings: %w", err)
 293→	}
 294→
 295→	fmt.Fprintln(w, "Entire is now enabled.")
 296→	return nil
 297→}
