 299→func runDisable(ctx context.Context, w io.Writer, useProjectSettings bool) error {
 300→	settings, err := LoadEntireSettings(ctx)
 301→	if err != nil {
 302→		return fmt.Errorf("failed to load settings: %w", err)
 303→	}
 304→
 305→	settings.Enabled = false
 306→
 307→	// If --project flag is specified, always write to project settings
 308→	if useProjectSettings {
 309→		if err := SaveEntireSettings(ctx, settings); err != nil {
 310→			return fmt.Errorf("failed to save settings: %w", err)
 311→		}
 312→	} else {
 313→		// Always write to local settings file (create if doesn't exist)
 314→		if err := SaveEntireSettingsLocal(ctx, settings); err != nil {
 315→			return fmt.Errorf("failed to save local settings: %w", err)
 316→		}
 317→	}
 318→
 319→	fmt.Fprintln(w, "Entire is now disabled.")
 320→	return nil
 321→}
