 323→// DisabledMessage is the message shown when Entire is disabled
 324→const DisabledMessage = "Entire is disabled. Run `entire enable` to re-enable."
 325→
 326→// checkDisabledGuard checks if Entire is disabled and prints a message if so.
 327→// Returns true if the caller should exit (i.e., Entire is disabled).
 328→// On error reading settings, defaults to enabled (returns false).
 329→func checkDisabledGuard(ctx context.Context, w io.Writer) bool {
 330→	enabled, err := IsEnabled(ctx)
 331→	if err != nil {
 332→		// Default to enabled on error
 333→		return false
 334→	}
 335→	if !enabled {
 336→		fmt.Fprintln(w, DisabledMessage)
 337→		return true
 338→	}
 339→	return false
 340→}
