 342→// uninstallDeselectedAgentHooks removes hooks for agents that were previously
 343→// installed but are not in the selected list. This handles the case where a user
 344→// re-runs `entire enable` and deselects an agent.
 345→func uninstallDeselectedAgentHooks(ctx context.Context, w io.Writer, selectedAgents []agent.Agent) error {
 346→	installedNames := GetAgentsWithHooksInstalled(ctx)
 347→	if len(installedNames) == 0 {
 348→		return nil
 349→	}
 350→
 351→	selectedSet := make(map[agent.AgentName]struct{}, len(selectedAgents))
 352→	for _, ag := range selectedAgents {
 353→		selectedSet[ag.Name()] = struct{}{}
 354→	}
 355→
 356→	var errs []error
 357→	for _, name := range installedNames {
 358→		if _, selected := selectedSet[name]; selected {
 359→			continue
 360→		}
 361→		ag, err := agent.Get(name)
 362→		if err != nil {
 363→			continue
 364→		}
 365→		hookAgent, ok := ag.(agent.HookSupport)
 366→		if !ok {
 367→			continue
 368→		}
 369→		if err := hookAgent.UninstallHooks(ctx); err != nil {
 370→			errs = append(errs, fmt.Errorf("failed to uninstall %s hooks: %w", ag.Type(), err))
 371→		} else {
 372→			fmt.Fprintf(w, "Removed %s hooks\n", ag.Type())
 373→		}
 374→	}
 375→	return errors.Join(errs...)
 376→}
