 378→// setupAgentHooks sets up hooks for a given agent.
 379→// Returns the number of hooks installed (0 if already installed).
 380→func setupAgentHooks(ctx context.Context, ag agent.Agent, localDev, forceHooks bool) (int, error) {
 381→	hookAgent, ok := ag.(agent.HookSupport)
 382→	if !ok {
 383→		return 0, fmt.Errorf("agent %s does not support hooks", ag.Name())
 384→	}
 385→
 386→	count, err := hookAgent.InstallHooks(ctx, localDev, forceHooks)
 387→	if err != nil {
 388→		return 0, fmt.Errorf("failed to install %s hooks: %w", ag.Name(), err)
 389→	}
 390→
 391→	return count, nil
 392→}
