 394→// detectOrSelectAgent tries to auto-detect agents, or prompts the user to select.
 395→// Returns the detected/selected agents and any error.
 396→//
 397→// On first run (no hooks installed):
 398→//   - Single detected agent: used automatically
 399→//   - Multiple/no detected agents: interactive multi-select prompt
 400→//
 401→// On re-run (hooks already installed):
 402→//   - Always shows the interactive multi-select
 403→//   - Pre-selects only agents that have hooks installed (respects prior deselection)
 404→//
 405→// selectFn overrides the interactive prompt for testing. When nil, the real form is used.
 406→// It receives available agent names and returns the selected names.
 407→func detectOrSelectAgent(ctx context.Context, w io.Writer, selectFn func(available []string) ([]string, error)) ([]agent.Agent, error) {
 408→	// Check for agents with hooks already installed (re-run detection)
 409→	installedAgentNames := GetAgentsWithHooksInstalled(ctx)
 410→	hasInstalledHooks := len(installedAgentNames) > 0
 411→
 412→	// Try auto-detection
 413→	detected := agent.DetectAll(ctx)
 414→
 415→	// First run: use existing auto-detect shortcuts
 416→	if !hasInstalledHooks {
 417→		switch {
 418→		case len(detected) == 1:
 419→			fmt.Fprintf(w, "Detected agent: %s\n\n", detected[0].Type())
 420→			return detected, nil
 421→
 422→		case len(detected) > 1:
 423→			agentTypes := make([]string, 0, len(detected))
 424→			for _, ag := range detected {
 425→				agentTypes = append(agentTypes, string(ag.Type()))
 426→			}
 427→			fmt.Fprintf(w, "Detected multiple agents: %s\n", strings.Join(agentTypes, ", "))
 428→			fmt.Fprintln(w)
 429→		}
 430→	}
 431→
 432→	// Check if we can prompt interactively
 433→	if !canPromptInteractively() {
 434→		if hasInstalledHooks {
 435→			// Re-run without TTY — keep currently installed agents
 436→			agents := make([]agent.Agent, 0, len(installedAgentNames))
 437→			for _, name := range installedAgentNames {
 438→				ag, err := agent.Get(name)
 439→				if err != nil {
 440→					continue
 441→				}
 442→				agents = append(agents, ag)
 443→			}
 444→			return agents, nil
 445→		}
 446→		if len(detected) > 0 {
 447→			return detected, nil
 448→		}
 449→		defaultAgent := agent.Default()
 450→		if defaultAgent == nil {
 451→			return nil, errors.New("no default agent available")
 452→		}
 453→		fmt.Fprintf(w, "Agent: %s (use --agent to change)\n\n", defaultAgent.Type())
 454→		return []agent.Agent{defaultAgent}, nil
 455→	}
 456→
 457→	if !hasInstalledHooks && len(detected) == 0 {
 458→		fmt.Fprintln(w, "No agent configuration detected (e.g., "+strings.Join(agent.StringList(), ", ")+").")
 459→		fmt.Fprintln(w, "This is normal - some agents don't require a config directory.")
 460→		fmt.Fprintln(w)
 461→	}
 462→
 463→	// Build pre-selection set.
 464→	// On re-run: only pre-select agents with hooks installed (respect prior deselection).
 465→	// On first run: pre-select all detected agents.
 466→	preSelectedSet := make(map[agent.AgentName]struct{})
 467→	if hasInstalledHooks {
 468→		for _, name := range installedAgentNames {
 469→			preSelectedSet[name] = struct{}{}
 470→		}
 471→	} else {
 472→		for _, ag := range detected {
 473→			preSelectedSet[ag.Name()] = struct{}{}
 474→		}
 475→	}
 476→
 477→	// Build options from registered agents
 478→	agentNames := agent.List()
 479→	options := make([]huh.Option[string], 0, len(agentNames))
 480→	for _, name := range agentNames {
 481→		ag, err := agent.Get(name)
 482→		if err != nil {
 483→			continue
 484→		}
 485→		// Only show agents that support hooks
 486→		if _, ok := ag.(agent.HookSupport); !ok {
 487→			continue
 488→		}
 489→		opt := huh.NewOption(string(ag.Type()), string(name))
 490→		if _, isPreSelected := preSelectedSet[name]; isPreSelected {
 491→			opt = opt.Selected(true)
 492→		}
 493→		options = append(options, opt)
 494→	}
 495→
 496→	if len(options) == 0 {
 497→		return nil, errors.New("no agents with hook support available")
 498→	}
 499→
 500→	// Collect available agent names for the selector
 501→	availableNames := make([]string, 0, len(options))
 502→	for _, opt := range options {
 503→		availableNames = append(availableNames, opt.Value)
 504→	}
 505→
 506→	var selectedAgentNames []string
 507→	if selectFn != nil {
 508→		var err error
 509→		selectedAgentNames, err = selectFn(availableNames)
 510→		if err != nil {
 511→			return nil, err
 512→		}
 513→		if len(selectedAgentNames) == 0 {
 514→			return nil, errors.New("no agents selected")
 515→		}
 516→	} else {
 517→		form := NewAccessibleForm(
 518→			huh.NewGroup(
 519→				huh.NewMultiSelect[string]().
 520→					Title("Which agents are you using?").
 521→					Description("Use space to select, enter to confirm.").
 522→					Options(options...).
 523→					Validate(func(selected []string) error {
 524→						if len(selected) == 0 {
 525→							return errors.New("please select at least one agent")
 526→						}
 527→						return nil
 528→					}).
 529→					Value(&selectedAgentNames),
 530→			),
 531→		)
 532→		if err := form.Run(); err != nil {
 533→			return nil, fmt.Errorf("agent selection cancelled: %w", err)
 534→		}
 535→	}
 536→
 537→	selectedAgents := make([]agent.Agent, 0, len(selectedAgentNames))
 538→	for _, name := range selectedAgentNames {
 539→		selectedAgent, err := agent.Get(agent.AgentName(name))
 540→		if err != nil {
 541→			return nil, fmt.Errorf("failed to get selected agent %s: %w", name, err)
 542→		}
 543→		selectedAgents = append(selectedAgents, selectedAgent)
 544→	}
 545→
 546→	agentTypes := make([]string, 0, len(selectedAgents))
 547→	for _, ag := range selectedAgents {
 548→		agentTypes = append(agentTypes, string(ag.Type()))
 549→	}
 550→	fmt.Fprintf(w, "\nSelected agents: %s\n\n", strings.Join(agentTypes, ", "))
 551→	return selectedAgents, nil
 552→}
