 554→// canPromptInteractively checks if we can show interactive prompts.
 555→// Returns false when running in CI, tests, or other non-interactive environments.
 556→func canPromptInteractively() bool {
 557→	// Check for test environment
 558→	if os.Getenv("ENTIRE_TEST_TTY") != "" {
 559→		return os.Getenv("ENTIRE_TEST_TTY") == "1"
 560→	}
 561→
 562→	// Check if /dev/tty is available
 563→	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
 564→	if err != nil {
 565→		return false
 566→	}
 567→	_ = tty.Close()
 568→	return true
 569→}
