 597→// setupAgentHooksNonInteractive sets up hooks for a specific agent non-interactively.
 598→// If strategyName is provided, it sets the strategy; otherwise uses default.
 599→func setupAgentHooksNonInteractive(ctx context.Context, w io.Writer, ag agent.Agent, localDev, forceHooks, skipPushSessions, telemetry bool) error {
 600→	agentName := ag.Name()
 601→	// Check if agent supports hooks
 602→	hookAgent, ok := ag.(agent.HookSupport)
 603→	if !ok {
 604→		return fmt.Errorf("agent %s does not support hooks", agentName)
 605→	}
 606→
 607→	fmt.Fprintf(w, "Agent: %s\n\n", ag.Type())
 608→
 609→	// Install agent hooks (agent hooks don't depend on settings)
 610→	installedHooks, err := hookAgent.InstallHooks(ctx, localDev, forceHooks)
 611→	if err != nil {
 612→		return fmt.Errorf("failed to install hooks for %s: %w", agentName, err)
 613→	}
 614→
 615→	// Check if this is a first-time setup BEFORE creating .entire directory
 616→	isFirstSetup := !settings.IsSetUp(ctx)
 617→
 618→	// Setup .entire directory
 619→	if _, err := setupEntireDirectory(ctx); err != nil {
 620→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 621→	}
 622→
 623→	// Load existing settings to preserve other options (like strategy_options.push)
 624→	settings, err := LoadEntireSettings(ctx)
 625→	if err != nil {
 626→		// If we can't load, start with defaults
 627→		settings = &EntireSettings{}
 628→	}
 629→	settings.Enabled = true
 630→	if localDev {
 631→		settings.LocalDev = localDev
 632→	}
 633→	// Set commit_linking and clean up deprecated strategy field.
 634→	if settings.CommitLinking == "" {
 635→		if isFirstSetup {
 636→			settings.CommitLinking = CommitLinkingAlways
 637→		} else {
 638→			settings.CommitLinking = CommitLinkingPrompt
 639→		}
 640→	}
 641→	settings.Strategy = "" //nolint:staticcheck // Intentionally clearing deprecated field during setup
 642→
 643→	// Set push_sessions option if --skip-push-sessions flag was provided
 644→	if skipPushSessions {
 645→		if settings.StrategyOptions == nil {
 646→			settings.StrategyOptions = make(map[string]interface{})
 647→		}
 648→		settings.StrategyOptions["push_sessions"] = false
 649→	}
 650→
 651→	// Handle telemetry for non-interactive mode
 652→	// Note: if telemetry is nil (not configured), it defaults to disabled
 653→	if !telemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
 654→		f := false
 655→		settings.Telemetry = &f
 656→	}
 657→
 658→	if err := SaveEntireSettings(ctx, settings); err != nil {
 659→		return fmt.Errorf("failed to save settings: %w", err)
 660→	}
 661→
 662→	if _, err := strategy.InstallGitHook(ctx, true, localDev); err != nil {
 663→		return fmt.Errorf("failed to install git hooks: %w", err)
 664→	}
 665→	strategy.CheckAndWarnHookManagers(ctx, w, localDev)
 666→
 667→	if installedHooks == 0 {
 668→		msg := fmt.Sprintf("Hooks for %s already installed", ag.Description())
 669→		if ag.IsPreview() {
 670→			msg += " (Preview)"
 671→		}
 672→		fmt.Fprintf(w, "%s\n", msg)
 673→	} else {
 674→		msg := fmt.Sprintf("Installed %d hooks for %s", installedHooks, ag.Description())
 675→		if ag.IsPreview() {
 676→			msg += " (Preview)"
 677→		}
 678→		fmt.Fprintf(w, "%s\n", msg)
 679→	}
 680→
 681→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplayProject)
 682→
 683→	if err := strategy.EnsureSetup(ctx); err != nil {
 684→		return fmt.Errorf("failed to setup strategy: %w", err)
 685→	}
 686→
 687→	fmt.Fprintln(w, "\nReady.")
 688→
 689→	return nil
 690→}
