 700→// determineSettingsTarget decides whether to write to settings.local.json based on:
 701→// - Whether settings.json already exists
 702→// - The --local and --project flags
 703→// Returns (useLocal, showNotification).
 704→func determineSettingsTarget(entireDir string, useLocal, useProject bool) (bool, bool) {
 705→	// Explicit --local flag always uses local settings
 706→	if useLocal {
 707→		return true, false
 708→	}
 709→
 710→	// Explicit --project flag always uses project settings
 711→	if useProject {
 712→		return false, false
 713→	}
 714→
 715→	// No flags specified - check if settings file exists
 716→	settingsPath := filepath.Join(entireDir, paths.SettingsFileName)
 717→	if _, err := os.Stat(settingsPath); err == nil {
 718→		// Settings file exists - auto-redirect to local with notification
 719→		return true, true
 720→	}
 721→
 722→	// Settings file doesn't exist - create it
 723→	return false, false
 724→}
