 738→	}
 739→	projectSettings.Strategy = "" //nolint:staticcheck // Intentionally clearing deprecated field
 740→	if projectSettings.CommitLinking == "" {
 741→		projectSettings.CommitLinking = settings.CommitLinkingPrompt
 742→	}
 743→	if err := settings.Save(ctx, projectSettings); err != nil {
 744→		return fmt.Errorf("saving project settings: %w", err)
 745→	}
 746→	return nil
 747→}
