 818→// shellCompletionComment is the comment preceding the completion line
 819→const shellCompletionComment = "# Entire CLI shell completion"
 820→
 821→// errUnsupportedShell is returned when the user's shell is not supported for completion.
 822→var errUnsupportedShell = errors.New("unsupported shell")
 823→
 824→// shellCompletionTarget returns the rc file path and completion lines for the
 825→// user's current shell.
 826→func shellCompletionTarget() (shellName, rcFile, completionLine string, err error) {
 827→	home, err := os.UserHomeDir()
 828→	if err != nil {
 829→		return "", "", "", fmt.Errorf("cannot determine home directory: %w", err)
 830→	}
 831→
 832→	shell := os.Getenv("SHELL")
 833→	switch {
 834→	case strings.Contains(shell, "zsh"):
 835→		return "Zsh",
 836→			filepath.Join(home, ".zshrc"),
 837→			"autoload -Uz compinit && compinit && source <(entire completion zsh)",
 838→			nil
 839→	case strings.Contains(shell, "bash"):
 840→		bashRC := filepath.Join(home, ".bashrc")
 841→		if _, err := os.Stat(filepath.Join(home, ".bash_profile")); err == nil {
 842→			bashRC = filepath.Join(home, ".bash_profile")
 843→		}
 844→		return "Bash",
 845→			bashRC,
 846→			"source <(entire completion bash)",
 847→			nil
 848→	case strings.Contains(shell, "fish"):
 849→		return "Fish",
 850→			filepath.Join(home, ".config", "fish", "config.fish"),
 851→			"entire completion fish | source",
 852→			nil
 853→	default:
 854→		return "", "", "", errUnsupportedShell
 855→	}
 856→}
 857→
 858→// promptShellCompletion offers to add shell completion to the user's rc file.
 859→// Only prompts if completion is not already configured.
 860→func promptShellCompletion(w io.Writer) error {
 861→	shellName, rcFile, completionLine, err := shellCompletionTarget()
 862→	if err != nil {
 863→		if errors.Is(err, errUnsupportedShell) {
 864→			fmt.Fprintf(w, "Note: Shell completion not available for your shell. Supported: zsh, bash, fish.\n")
 865→			return nil
 866→		}
 867→		return fmt.Errorf("shell completion: %w", err)
 868→	}
 869→
 870→	if isCompletionConfigured(rcFile) {
 871→		fmt.Fprintf(w, "✓ Shell completion already configured in %s\n", rcFile)
 872→		return nil
 873→	}
 874→
 875→	var selected string
 876→	form := NewAccessibleForm(
 877→		huh.NewGroup(
 878→			huh.NewSelect[string]().
 879→				Title(fmt.Sprintf("Enable shell completion? (detected: %s)", shellName)).
 880→				Options(
 881→					huh.NewOption("Yes", "yes"),
 882→					huh.NewOption("No", "no"),
 883→				).
 884→				Value(&selected),
 885→		),
 886→	)
 887→
 888→	if err := form.Run(); err != nil {
 889→		//nolint:nilerr // User cancelled - not a fatal error, just skip
 890→		return nil
 891→	}
 892→
 893→	if selected != "yes" {
 894→		return nil
 895→	}
 896→
 897→	if err := appendShellCompletion(rcFile, completionLine); err != nil {
 898→		return fmt.Errorf("failed to update %s: %w", rcFile, err)
 899→	}
 900→
 901→	fmt.Fprintf(w, "✓ Shell completion added to %s\n", rcFile)
 902→	fmt.Fprintln(w, "  Restart your shell to activate")
 903→
 904→	return nil
 905→}
 906→
 907→// isCompletionConfigured checks if shell completion is already in the rc file.
 908→func isCompletionConfigured(rcFile string) bool {
 909→	//nolint:gosec // G304: rcFile is constructed from home dir + known filename, not user input
 910→	content, err := os.ReadFile(rcFile)
 911→	if err != nil {
 912→		return false // File doesn't exist or can't read, treat as not configured
 913→	}
 914→	return strings.Contains(string(content), "entire completion")
 915→}
 916→
 917→// appendShellCompletion adds the completion line to the rc file.
 918→func appendShellCompletion(rcFile, completionLine string) error {
 919→	if err := os.MkdirAll(filepath.Dir(rcFile), 0o700); err != nil {
 920→		return fmt.Errorf("creating directory: %w", err)
 921→	}
 922→	//nolint:gosec // G302: Shell rc files need 0644 for user readability
 923→	f, err := os.OpenFile(rcFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
 924→	if err != nil {
 925→		return fmt.Errorf("opening file: %w", err)
 926→	}
 927→	defer f.Close()
 928→
 929→	_, err = f.WriteString("\n" + shellCompletionComment + "\n" + completionLine + "\n")
 930→	if err != nil {
 931→		return fmt.Errorf("writing completion: %w", err)
 932→	}
 933→	return nil
 934→}
