 979→// runUninstall completely removes Entire from the repository.
 980→func runUninstall(ctx context.Context, w, errW io.Writer, force bool) error {
 981→	// Check if we're in a git repository
 982→	if _, err := paths.WorktreeRoot(ctx); err != nil {
 983→		fmt.Fprintln(errW, "Not a git repository. Nothing to uninstall.")
 984→		return NewSilentError(errors.New("not a git repository"))
 985→	}
 986→
 987→	// Gather counts for display
 988→	sessionStateCount := countSessionStates(ctx)
 989→	shadowBranchCount := countShadowBranches(ctx)
 990→	gitHooksInstalled := strategy.IsGitHookInstalled(ctx)
 991→	agentsWithInstalledHooks := GetAgentsWithHooksInstalled(ctx)
 992→	entireDirExists := checkEntireDirExists(ctx)
 993→
 994→	// Check if there's anything to uninstall
 995→	if !entireDirExists && !gitHooksInstalled && sessionStateCount == 0 &&
 996→		shadowBranchCount == 0 && len(agentsWithInstalledHooks) == 0 {
 997→		fmt.Fprintln(w, "Entire is not installed in this repository.")
 998→		return nil
 999→	}
1000→
1001→	// Show confirmation prompt unless --force
1002→	if !force {
1003→		fmt.Fprintln(w, "\nThis will completely remove Entire from this repository:")
1004→		if entireDirExists {
1005→			fmt.Fprintln(w, "  - .entire/ directory")
1006→		}
1007→		if gitHooksInstalled {
1008→			fmt.Fprintln(w, "  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
1009→		}
1010→		if sessionStateCount > 0 {
1011→			fmt.Fprintf(w, "  - Session state files (%d)\n", sessionStateCount)
1012→		}
1013→		if shadowBranchCount > 0 {
1014→			fmt.Fprintf(w, "  - Shadow branches (%d)\n", shadowBranchCount)
1015→		}
1016→		if len(agentsWithInstalledHooks) > 0 {
1017→			displayNames := make([]string, 0, len(agentsWithInstalledHooks))
1018→			for _, name := range agentsWithInstalledHooks {
1019→				if ag, err := agent.Get(name); err == nil {
1020→					displayNames = append(displayNames, string(ag.Type()))
1021→				}
1022→			}
1023→			fmt.Fprintf(w, "  - Agent hooks (%s)\n", strings.Join(displayNames, ", "))
1024→		}
1025→		fmt.Fprintln(w)
1026→
1027→		var confirmed bool
1028→		form := NewAccessibleForm(
1029→			huh.NewGroup(
1030→				huh.NewConfirm().
1031→					Title("Are you sure you want to uninstall Entire?").
1032→					Affirmative("Yes, uninstall").
1033→					Negative("Cancel").
1034→					Value(&confirmed),
1035→			),
1036→		)
1037→
1038→		if err := form.Run(); err != nil {
1039→			return fmt.Errorf("confirmation cancelled: %w", err)
1040→		}
1041→
1042→		if !confirmed {
1043→			fmt.Fprintln(w, "Uninstall cancelled.")
1044→			return nil
1045→		}
1046→	}
1047→
1048→	fmt.Fprintln(w, "\nUninstalling Entire CLI...")
1049→
1050→	// 1. Remove agent hooks (lowest risk)
1051→	if err := removeAgentHooks(ctx, w); err != nil {
1052→		fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %v\n", err)
1053→	}
1054→
1055→	// 2. Remove git hooks
1056→	removed, err := strategy.RemoveGitHook(ctx)
1057→	if err != nil {
1058→		fmt.Fprintf(errW, "Warning: failed to remove git hooks: %v\n", err)
1059→	} else if removed > 0 {
1060→		fmt.Fprintf(w, "  Removed git hooks (%d)\n", removed)
1061→	}
1062→
1063→	// 3. Remove session state files
1064→	statesRemoved, err := removeAllSessionStates(ctx)
1065→	if err != nil {
1066→		fmt.Fprintf(errW, "Warning: failed to remove session states: %v\n", err)
1067→	} else if statesRemoved > 0 {
1068→		fmt.Fprintf(w, "  Removed session states (%d)\n", statesRemoved)
1069→	}
1070→
1071→	// 4. Remove .entire/ directory
1072→	if err := removeEntireDirectory(ctx); err != nil {
1073→		fmt.Fprintf(errW, "Warning: failed to remove .entire directory: %v\n", err)
1074→	} else if entireDirExists {
1075→		fmt.Fprintln(w, "  Removed .entire directory")
1076→	}
1077→
1078→	// 5. Remove shadow branches
1079→	branchesRemoved, err := removeAllShadowBranches(ctx)
1080→	if err != nil {
1081→		fmt.Fprintf(errW, "Warning: failed to remove shadow branches: %v\n", err)
1082→	} else if branchesRemoved > 0 {
1083→		fmt.Fprintf(w, "  Removed %d shadow branches\n", branchesRemoved)
1084→	}
1085→
1086→	fmt.Fprintln(w, "\nEntire CLI uninstalled successfully.")
1087→	return nil
1088→}
