1122→// removeAgentHooks removes hooks from all agents that support hooks.
1123→func removeAgentHooks(ctx context.Context, w io.Writer) error {
1124→	var errs []error
1125→	for _, name := range agent.List() {
1126→		ag, err := agent.Get(name)
1127→		if err != nil {
1128→			continue
1129→		}
1130→		hs, ok := ag.(agent.HookSupport)
1131→		if !ok {
1132→			continue
1133→		}
1134→		wasInstalled := hs.AreHooksInstalled(ctx)
1135→		if err := hs.UninstallHooks(ctx); err != nil {
1136→			errs = append(errs, err)
1137→		} else if wasInstalled {
1138→			fmt.Fprintf(w, "  Removed %s hooks\n", ag.Type())
1139→		}
1140→	}
1141→	return errors.Join(errs...)
1142→}
1143→
1144→// removeAllSessionStates removes all session state files and the directory.
1145→func removeAllSessionStates(ctx context.Context) (int, error) {
1146→	store, err := session.NewStateStore(ctx)
1147→	if err != nil {
