 76→// Load loads the Entire settings from .entire/settings.json,
 77→// then applies any overrides from .entire/settings.local.json if it exists.
 78→// Returns default settings if neither file exists.
 79→// Works correctly from any subdirectory within the repository.
 80→func Load(ctx context.Context) (*EntireSettings, error) {
 81→	// Get absolute paths for settings files
 82→	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
 83→	if err != nil {
 84→		settingsFileAbs = EntireSettingsFile // Fallback to relative
 85→	}
 86→	localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
 87→	if err != nil {
 88→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
 89→	}
 90→
 91→	// Load base settings
 92→	settings, err := loadFromFile(settingsFileAbs)
 93→	if err != nil {
 94→		return nil, fmt.Errorf("reading settings file: %w", err)
 95→	}
 96→
 97→	// Apply local overrides if they exist
 98→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
 99→	if err != nil {
100→		if !os.IsNotExist(err) {
101→			return nil, fmt.Errorf("reading local settings file: %w", err)
102→		}
103→		// Local file doesn't exist, continue without overrides
104→	} else {
105→		if err := mergeJSON(settings, localData); err != nil {
106→			return nil, fmt.Errorf("merging local settings: %w", err)
107→		}
108→	}
109→
110→	return settings, nil
111→}
