120→// loadFromFile loads settings from a specific file path.
121→// Returns default settings if the file doesn't exist.
122→func loadFromFile(filePath string) (*EntireSettings, error) {
123→	settings := &EntireSettings{
124→		Enabled: true, // Default to enabled
125→	}
126→
127→	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
128→	if err != nil {
129→		if os.IsNotExist(err) {
130→			return settings, nil
131→		}
132→		return nil, fmt.Errorf("%w", err)
133→	}
134→
135→	dec := json.NewDecoder(bytes.NewReader(data))
136→	dec.DisallowUnknownFields()
137→	if err := dec.Decode(settings); err != nil {
138→		return nil, fmt.Errorf("parsing settings file: %w", err)
139→	}
140→
141→	// Validate commit_linking if set
142→	if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
143→		return nil, fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
144→	}
145→
146→	return settings, nil
147→}
