149→// mergeJSON merges JSON data into existing settings.
150→// Only non-zero values from the JSON override existing settings.
151→func mergeJSON(settings *EntireSettings, data []byte) error {
152→	// First, validate that there are no unknown keys using strict decoding
153→	dec := json.NewDecoder(bytes.NewReader(data))
154→	dec.DisallowUnknownFields()
155→	var temp EntireSettings
156→	if err := dec.Decode(&temp); err != nil {
157→		return fmt.Errorf("parsing JSON: %w", err)
158→	}
159→
160→	// Parse into a map to check which fields are present
161→	var raw map[string]json.RawMessage
162→	if err := json.Unmarshal(data, &raw); err != nil {
163→		return fmt.Errorf("parsing JSON: %w", err)
164→	}
165→
166→	// Override enabled if present
167→	if enabledRaw, ok := raw["enabled"]; ok {
168→		var e bool
169→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
170→			return fmt.Errorf("parsing enabled field: %w", err)
171→		}
172→		settings.Enabled = e
173→	}
174→
175→	// Override local_dev if present
176→	if localDevRaw, ok := raw["local_dev"]; ok {
177→		var ld bool
178→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
179→			return fmt.Errorf("parsing local_dev field: %w", err)
180→		}
181→		settings.LocalDev = ld
182→	}
183→
184→	// Override log_level if present and non-empty
185→	if logLevelRaw, ok := raw["log_level"]; ok {
186→		var ll string
187→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
188→			return fmt.Errorf("parsing log_level field: %w", err)
189→		}
190→		if ll != "" {
191→			settings.LogLevel = ll
192→		}
193→	}
194→
195→	// Merge strategy_options if present
196→	if optionsRaw, ok := raw["strategy_options"]; ok {
197→		var opts map[string]any
198→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
199→			return fmt.Errorf("parsing strategy_options field: %w", err)
200→		}
201→		if settings.StrategyOptions == nil {
202→			settings.StrategyOptions = opts
203→		} else {
204→			for k, v := range opts {
205→				settings.StrategyOptions[k] = v
206→			}
207→		}
208→	}
209→
210→	// Override telemetry if present
211→	if telemetryRaw, ok := raw["telemetry"]; ok {
212→		var t bool
213→		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
214→			return fmt.Errorf("parsing telemetry field: %w", err)
215→		}
216→		settings.Telemetry = &t
217→	}
218→
219→	// Override commit_linking if present and non-empty
220→	if commitLinkingRaw, ok := raw["commit_linking"]; ok {
221→		var cl string
222→		if err := json.Unmarshal(commitLinkingRaw, &cl); err != nil {
223→			return fmt.Errorf("parsing commit_linking field: %w", err)
224→		}
225→		if cl != "" {
226→			switch cl {
227→			case CommitLinkingAlways, CommitLinkingPrompt:
228→				settings.CommitLinking = cl
229→			default:
230→				return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", cl, CommitLinkingAlways, CommitLinkingPrompt)
231→			}
232→		}
233→	}
234→
235→	return nil
236→}
